#!/usr/bin/env python3
"""Independent naive reference implementation for differential testing.

Deliberately different structure: a plain event list re-sorted each step, no
heap, cache usage recomputed by scanning, subset checks done with sets.
Written directly from the task specification.
"""
import json
import sys

RED = 0


def solve(doc):
    n = doc["n"]
    cap = doc["capacity"]
    edges = doc["edges"]
    rounds_in = doc["rounds"]
    ens = len(edges)

    # outgoing edges per node
    outs = {}
    for i in range(n):
        outs[i] = []
    for i, e in enumerate(edges):
        outs[e["u"]].append(i)

    M = {
        "host_probe_tx": len(rounds_in),
        "network_ping_tx": 0,
        "network_ack_tx": 0,
        "host_ack_tx": 0,
        "deduplicated_ping": 0,
        "capacity_drops": 0,
        "late_ping": 0,
        "ignored_ack": 0,
        "allocations": 0,
    }
    peak_node = [0] * n
    peak_total = 0

    # events: dict time, prio, round, key, kind, payload
    events = []
    rndinfo = []
    for rid, rr in enumerate(rounds_in):
        deadline = rr["launch_us"] + rr["timeout_us"]
        rndinfo.append({
            "deadline": deadline,
            "launch": rr["launch_us"],
            "host_delay": rr["host_delay_us"],
            "drop_host_ack": rr["drop_host_ack"],
            "drop_ping": set(rr["drop_ping"]),
            "drop_ack": set(rr["drop_ack"]),
            "started": False,
            "final_us": None,
            "complete": None,
            "proof": None,
            "host_delivery": None,
        })
        events.append({"t": rr["launch_us"], "p": 2, "r": rid, "k": -1, "kind": "ping"})
        events.append({"t": deadline + 1, "p": 1, "r": rid, "k": -1, "kind": "release"})

    # cache: (round,node) -> entry dict
    cache = {}

    def usage(node):
        cnt = 0
        for (rid, nd) in cache:
            if nd == node:
                cnt += 1
        return cnt

    def record_peaks():
        nonlocal peak_total
        for node in range(n):
            u = usage(node)
            if u > peak_node[node]:
                peak_node[node] = u
        tot = len(cache)
        if tot > peak_total:
            peak_total = tot

    def emit(time, rid, kind, key, payload=None):
        p = {"release": 1, "ping": 2, "ack": 3, "timeout": 4, "hostack": 5}[kind]
        events.append({"t": time, "p": p, "r": rid, "k": key, "kind": kind,
                       "payload": payload})

    def do_finalize(rid, node, ent, complete):
        ent["final"] = True
        ent["complete"] = complete
        proof = frozenset(ent["proof"])
        info = rndinfo[rid]
        if node == 0:
            info["final_us"] = cur_time
            info["complete"] = complete
            info["proof"] = sorted(proof)
            M["host_ack_tx"] += 1
            if not info["drop_host_ack"]:
                emit(cur_time + info["host_delay"], rid, "hostack", -1)
        for pedge in sorted(ent["parents"]):
            M["network_ack_tx"] += 1
            if pedge in info["drop_ack"]:
                continue
            emit(cur_time + edges[pedge]["ack_us"], rid, "ack", pedge,
                 (proof, complete))
        ent["parents"] = set()

    last_time = 0
    while events:
        best = None
        for ev in events:
            keyt = (ev["t"], ev["p"], ev["r"], ev["k"])
            if best is None or keyt < (best["t"], best["p"], best["r"], best["k"]):
                best = ev
        events.remove(best)
        cur_time = best["t"]
        last_time = cur_time
        rid = best["r"]
        info = rndinfo[rid]
        kind = best["kind"]
        if kind == "ping":
            if best["k"] == -1:
                node = 0
                inc = None
            else:
                node = edges[best["k"]]["v"]
                inc = best["k"]
            if cur_time > info["deadline"]:
                M["late_ping"] += 1
            elif (rid, node) in cache:
                M["deduplicated_ping"] += 1
                ent = cache[(rid, node)]
                if inc is not None:
                    if ent["final"]:
                        M["network_ack_tx"] += 1
                        if inc not in info["drop_ack"]:
                            emit(cur_time + edges[inc]["ack_us"], rid, "ack", inc,
                                 (frozenset(ent["proof"]), ent["complete"]))
                    else:
                        ent["parents"].add(inc)
            elif usage(node) >= cap[node]:
                M["capacity_drops"] += 1
            else:
                ent = {"parents": set(), "credited": set(), "proof": set(),
                       "final": False, "cvals": [], "out": list(outs[node])}
                if inc is not None:
                    ent["parents"].add(inc)
                cache[(rid, node)] = ent
                M["allocations"] += 1
                record_peaks()
                if node == 0:
                    info["started"] = True
                emit(info["deadline"], rid, "timeout", node)
                for oe in outs[node]:
                    M["network_ping_tx"] += 1
                    if oe in info["drop_ping"]:
                        continue
                    emit(cur_time + edges[oe]["ping_us"], rid, "ping", oe)
                if not outs[node]:
                    do_finalize(rid, node, ent, True)
        elif kind == "ack":
            node = edges[best["k"]]["u"]
            ent = cache.get((rid, node))
            if ent is None or ent["final"] or best["k"] in ent["credited"]:
                M["ignored_ack"] += 1
            else:
                ent["credited"].add(best["k"])
                proof, comp = best["payload"]
                ent["proof"].add(best["k"])
                ent["proof"] |= proof
                ent["cvals"].append(comp)
                if len(ent["credited"]) == len(outs[node]):
                    ok = all(ent["cvals"])
                    do_finalize(rid, node, ent, ok)
        elif kind == "timeout":
            node = best["k"]
            ent = cache.get((rid, node))
            if ent is not None and not ent["final"]:
                do_finalize(rid, node, ent, False)
        elif kind == "hostack":
            info["host_delivery"] = cur_time
        elif kind == "release":
            for key in [k for k in cache if k[0] == rid]:
                del cache[key]

    # ---- topology paths and signature classes (independent enumeration by BFS) ----
    frontier = [(0, [], [])]  # node, edge path, node path
    allpaths = []
    while frontier:
        node, epath, npath = frontier.pop()
        if node == n - 1 and epath:
            allpaths.append(list(epath))
        for oe in outs[node]:
            v = edges[oe]["v"]
            frontier.append((v, epath + [oe], npath + [node]))
    if n - 1 == 0:
        allpaths = []
    # note: source==destination cannot happen since n>=2 and source is 0
    classmap = {}
    for p in allpaths:
        sig = tuple(edges[e]["label"] for e in p)
        classmap.setdefault(sig, []).append(p)
    classes = []
    observed = 0
    uniq = 0
    amb = 0
    upper = 0
    for sig in sorted(classmap):
        plist = classmap[sig]
        evr = []
        for rid in range(len(rounds_in)):
            info = rndinfo[rid]
            if info["host_delivery"] is None:
                continue
            proof = set(info["proof"] or [])
            hit = False
            for p in plist:
                if all(e in proof for e in p):
                    hit = True
                    break
            if hit:
                evr.append(rid)
        cnt = len(plist)
        if evr:
            observed += 1
            upper += cnt
            if cnt == 1:
                uniq += 1
            else:
                amb += 1
        if cnt == 1:
            wit = [plist[0]]
        else:
            wit = [plist[0], plist[1]]
        classes.append({
            "signature": list(sig),
            "candidate_count": cnt,
            "evidence_rounds": evr,
            "state": "unobserved" if not evr else ("unique" if cnt == 1 else "ambiguous"),
            "candidate_witnesses": wit,
        })
    observable = len(classes)
    if observable == 0:
        cov = "no-routes"
    elif observed == 0:
        cov = "no-evidence"
    elif observed == observable:
        cov = "complete"
    else:
        cov = "partial"

    rounds_out = []
    for rid in range(len(rounds_in)):
        info = rndinfo[rid]
        if info["started"]:
            rounds_out.append({
                "id": rid,
                "started": True,
                "source_final_us": info["final_us"],
                "source_complete": info["complete"],
                "host_delivery_us": info["host_delivery"],
                "source_proof": sorted(info["proof"]),
            })
        else:
            rounds_out.append({
                "id": rid, "started": False, "source_final_us": None,
                "source_complete": None, "host_delivery_us": None,
                "source_proof": [],
            })
    metrics = dict(M)
    metrics["cache_peak"] = peak_node
    metrics["peak_entries"] = peak_total
    metrics["end_us"] = last_time if rounds_in else 0
    summary = {
        "topology_paths": len(allpaths),
        "observable_classes": observable,
        "observed_classes": observed,
        "unique_observed_classes": uniq,
        "ambiguous_observed_classes": amb,
        "path_evidence_lower": observed,
        "path_evidence_upper": upper,
        "coverage_status": cov,
    }
    return {"rounds": rounds_out, "metrics": metrics, "classes": classes,
            "summary": summary}


if __name__ == "__main__":
    doc = json.loads(sys.stdin.read())
    print(json.dumps(solve(doc), indent=1))
